package com.nexacrm.service;  import com.nexacrm.dto.NotificationDTO; import com.nexacrm.dto.PageResponse; import com.nexacrm.exception.ResourceNotFoundException; import com.nexacrm.model.Notification; import com.nexacrm.model.User; import com.nexacrm.repository.NotificationRepository; import com.nexacrm.repository.UserRepository; import com.nexacrm.security.TenantContext; import com.nexacrm.websocket.NotificationPublisher; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.transaction.support.TransactionSynchronization; import org.springframework.transaction.support.TransactionSynchronizationManager;  import java.util.Collection; import java.util.List; import java.util.Locale; import java.util.Objects; import java.util.stream.Collectors;  @Service @RequiredArgsConstructor @Slf4j @Transactional public class NotificationService {      private Long tenantId() { return TenantContext.currentTenantId(); }      private final NotificationRepository notificationRepository;     private final UserRepository userRepository;     private final NotificationPublisher notificationPublisher;      @Transactional(readOnly = true)     public PageResponse<NotificationDTO> findForCurrentUser(int page, int size) {         User user = currentUser();         Page<Notification> result = notificationRepository             .findByTenantIdAndUser_IdAndDeletedFalseOrderByCreatedAtDesc(tenantId(), user.getId(), PageRequest.of(page, size));         return PageResponse.<NotificationDTO>builder()             .content(result.getContent().stream().map(this::toDTO).collect(Collectors.toList()))             .page(result.getNumber()).size(result.getSize())             .total(result.getTotalElements()).totalPages(result.getTotalPages())             .first(result.isFirst()).last(result.isLast())             .build();     }      @Transactional(readOnly = true)     public long getUnreadCount() {         return notificationRepository.countByTenantIdAndUser_IdAndIsReadFalseAndDeletedFalse(tenantId(), currentUser().getId());     }      public NotificationDTO markRead(String id) {         String currentUserId = currentUser().getId();         Notification n = notificationRepository.findByIdAndTenantIdAndUser_IdAndDeletedFalse(id, tenantId(), currentUserId)             .orElseThrow(() -> new ResourceNotFoundException("Notification not found: " + id));         n.setIsRead(true);         return toDTO(notificationRepository.save(n));     }      public int markAllRead() {         var unread = notificationRepository.findByTenantIdAndUser_IdAndIsReadFalseAndDeletedFalse(tenantId(), currentUser().getId());         unread.forEach(n -> n.setIsRead(true));         notificationRepository.saveAll(unread);         return unread.size();     }      public void delete(String id) {         String currentUserId = currentUser().getId();         Notification n = notificationRepository.findByIdAndTenantIdAndUser_IdAndDeletedFalse(id, tenantId(), currentUserId)             .orElseThrow(() -> new ResourceNotFoundException("Notification not found: " + id));         n.setDeleted(true);         notificationRepository.save(n);     }      public List<NotificationDTO> notifyLeadCreated(String leadName, String source, String leadId) {         String sourceName = normalizeLabel(source, "Unknown source");         String targetName = normalizeLabel(leadName, "New lead");         return notifyActiveUsers(             tenantId(),             Notification.NotificationType.LEAD,             "New Lead",             "New lead from " + sourceName + ": " + targetName,             "/leads",             "lead",             leadId,             null         );     }      public List<NotificationDTO> notifyInboundMessage(String channel, String contactLabel, String messageBody) {         return notifyCommunicationMessage(channel, true, contactLabel, messageBody);     }      public List<NotificationDTO> notifyOutboundMessage(String channel, String contactLabel, String messageBody) {         return notifyCommunicationMessage(channel, false, contactLabel, messageBody);     }      public List<NotificationDTO> notifyActiveUsers(         Long tenantId,         Notification.NotificationType type,         String title,         String message,         String actionUrl,         String entityType,         String entityId,         Notification.NotificationDirection direction     ) {         List<User> recipients = userRepository.findByTenantIdAndDeletedFalse(tenantId).stream()             .filter(user -> Boolean.TRUE.equals(user.getIsActive()))             .filter(user -> user.getEmail() != null && !user.getEmail().isBlank())             .toList();         return notifyUsers(recipients, type, title, message, actionUrl, entityType, entityId, direction);     }      public List<NotificationDTO> notifyUsers(         Collection<User> recipients,         Notification.NotificationType type,         String title,         String message,         String actionUrl,         String entityType,         String entityId,         Notification.NotificationDirection direction     ) {         if (recipients == null || recipients.isEmpty()) {             return List.of();         }          List<NotificationDTO> created = recipients.stream()             .filter(Objects::nonNull)             .map(recipient -> createNotification(recipient, type, title, message, actionUrl, entityType, entityId, direction))             .toList();          created.forEach(this::publishAfterCommit);          return created;     }      private User currentUser() {         String email = SecurityContextHolder.getContext().getAuthentication().getName();         return userRepository.findByEmailAndTenantIdAndDeletedFalse(email, tenantId())             .orElseThrow(() -> new ResourceNotFoundException("User not found: " + email));     }      private NotificationDTO createNotification(         User recipient,         Notification.NotificationType type,         String title,         String message,         String actionUrl,         String entityType,         String entityId,         Notification.NotificationDirection direction     ) {         Notification notification = Notification.builder()             .user(recipient)             .title(normalizeLabel(title, "Notification"))             .message(normalizeLabel(message, ""))             .type(type != null ? type : Notification.NotificationType.SYSTEM)             .isRead(false)             .actionUrl(normalizeLabel(actionUrl, ""))             .entityType(normalizeLabel(entityType, ""))             .entityId(normalizeLabel(entityId, ""))             .direction(direction)             .build();         notification.setTenantId(recipient.getTenantId() != null ? recipient.getTenantId() : tenantId());          Notification saved = notificationRepository.save(notification);         return toDTO(saved);     }      private NotificationDTO toDTO(Notification n) {         return NotificationDTO.builder()             .id(n.getId())             .userId(n.getUser() != null ? n.getUser().getId() : null)             .title(n.getTitle())             .message(n.getMessage())             .type(n.getType())             .isRead(n.getIsRead())             .actionUrl(n.getActionUrl())             .entityType(n.getEntityType())             .entityId(n.getEntityId())             .direction(n.getDirection())             .createdAt(n.getCreatedAt())             .build();     }      private String normalizeLabel(String value, String fallback) {         String trimmed = value == null ? "" : value.trim();         return trimmed.isBlank() ? fallback : trimmed;     }      private String formatChannelLabel(String channel) {         String normalized = normalizeLabel(channel, "message").toLowerCase(Locale.ROOT);         return switch (normalized) {             case "whatsapp" -> "WhatsApp";             case "facebook" -> "Facebook";             case "instagram" -> "Instagram";             case "email" -> "Email";             case "sms" -> "SMS";             case "linkedin" -> "LinkedIn";             case "reddit" -> "Reddit";             default -> normalized.substring(0, 1).toUpperCase(Locale.ROOT) + normalized.substring(1);         };     }      private List<NotificationDTO> notifyCommunicationMessage(String channel, boolean inbound, String contactLabel, String messageBody) {         String channelName = formatChannelLabel(channel);         String contactName = normalizeLabel(contactLabel, "Unknown contact");         String preview = shorten(normalizeLabel(messageBody, inbound ? "New message" : "Sent message"));         String title = inbound             ? ("Email".equals(channelName) ? "New Email" : "New " + channelName + " Message")             : ("Email".equals(channelName) ? "Email Sent" : channelName + " Message Sent");         String message = inbound             ? "Received from " + contactName + ": " + preview             : "Sent to " + contactName + ": " + preview;          return notifyActiveUsers(             tenantId(),             Notification.NotificationType.COMMUNICATION,             title,             message,             "/communication",             "communication",             null,             inbound ? Notification.NotificationDirection.INBOUND : Notification.NotificationDirection.OUTBOUND         );     }      private String shorten(String value) {         String trimmed = normalizeLabel(value, "");         if (trimmed.length() <= 120) {             return trimmed;         }         return trimmed.substring(0, 117).trim() + "...";     }      private void publishAfterCommit(NotificationDTO dto) {         Runnable pushTask = () -> {             try {                 if (dto.getUserId() != null) {                     userRepository.findByIdAndTenantIdAndDeletedFalse(dto.getUserId(), tenantId())                         .ifPresent(user -> notificationPublisher.sendToUser(user.getEmail(), dto));                 }             } catch (Exception ex) {                 log.warn("Live notification push failed for notification {}: {}", dto.getId(), ex.getMessage());             }         };          if (TransactionSynchronizationManager.isActualTransactionActive()) {             TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {                 @Override                 public void afterCommit() {                     pushTask.run();                 }             });             return;         }          pushTask.run();     } }